import sys,json,re,time,threading,urllib.request,urllib.parse
from pathlib import Path
root=Path.cwd();sys.path.insert(0,str(root/'tool/playback_benchmark'))
from run_resources import collect
out=Path(sys.argv[1]);done=threading.Event();observations=[]
def monitor():
    uri=None;isolate=None;seen=set()
    def rpc(method,params={}):
        target=uri+method+'?'+urllib.parse.urlencode(params)
        with urllib.request.urlopen(target,timeout=2) as response:
            raw=response.read(8*1024*1024+1)
        if len(raw)>8*1024*1024: raise ValueError('limit')
        obj=json.loads(raw)
        if 'error' in obj: return {'errorCode':obj['error'].get('code')}
        return obj.get('result',obj)
    while not done.is_set():
        log=out/'playback.log'
        if log.exists():
            text=log.read_text(errors='replace')
            if uri is None:
                match=re.search(r'Connecting to Flutter application at (http://[^\s]+)',text)
                if match:
                    candidate=match[1];parsed=urllib.parse.urlparse(candidate)
                    if parsed.hostname not in ('127.0.0.1','localhost','::1'): raise ValueError('not loopback')
                    uri=candidate.rstrip('/')+'/'
            for line in text.splitlines():
                if 'YL_RESOURCE_SERIES=' not in line: continue
                try: row=json.loads(line.split('YL_RESOURCE_SERIES=',1)[1])
                except ValueError: continue
                n=row['attempt']
                if n in seen:continue
                seen.add(n);result={'attempt':n,'status':'unavailable','hostMonotonicNs':time.monotonic_ns()}
                try:
                    if uri is None: raise ValueError('no uri')
                    if isolate is None:
                        vm=rpc('getVM');isolate=next(i['id'] for i in vm.get('isolates',[]) if i.get('name')=='main')
                    memory=rpc('getMemoryUsage',{'isolateId':isolate})
                    if memory.get('type')=='MemoryUsage':
                        result.update(status='observed',memory={k:memory[k] for k in ['heapUsage','heapCapacity','externalUsage']})
                    else:result['errorCode']=memory.get('errorCode')
                    if n in (1,10):
                        allocation=rpc('getAllocationProfile',{'isolateId':isolate,'gc':'false','reset':'false'})
                        result['allocationType']=allocation.get('type');result['allocationErrorCode']=allocation.get('errorCode')
                        result['playerClasses']=[{'name':m.get('class',{}).get('name'),'instancesCurrent':m.get('instancesCurrent'),'bytesCurrent':m.get('bytesCurrent')} for m in allocation.get('members',[]) if re.fullmatch(r'[A-Za-z0-9_]*[Pp]layer[A-Za-z0-9_]*',m.get('class',{}).get('name',''))]
                except Exception: pass
                observations.append(result)
                (out/'vm-memory.json').write_text(json.dumps(observations,indent=2)+'\n')
        done.wait(.1)
thread=threading.Thread(target=monitor,daemon=True);thread.start()
try:passed=collect(out,'/Users/yy2021_8689/flutter/bin/flutter',profile_cycles=True)
finally:done.set();thread.join(3)
print('collected',passed,'heap snapshots',[(r['attempt'],r['status'],r.get('memory')) for r in observations])

