import struct,hashlib,json
from pathlib import Path

def sections(path):
 data=path.read_bytes()
 assert struct.unpack_from('<I',data)[0]==0xfeedfacf
 count=struct.unpack_from('<I',data,16)[0];offset=32;out={}
 for _ in range(count):
  cmd,length=struct.unpack_from('<II',data,offset)
  if cmd==0x19:
   nsects=struct.unpack_from('<I',data,offset+64)[0]
   for n in range(nsects):
    s=struct.unpack_from('<16s16sQQIIIIIIII',data,offset+72+n*80)
    name=s[1].split(b'\0')[0].decode()+','+s[0].split(b'\0')[0].decode()
    zero=s[8]&0xff in (1,12,18)
    out[name]={'bytes':s[3],'sha256':None if zero else hashlib.sha256(data[s[4]:s[4]+s[3]]).hexdigest(),'zeroFill':zero}
  offset+=length
 return out
if __name__=='__main__':
 root=Path('/private/tmp/yl-retention-attribution');r={n:sections(root/n/'resources.dylib') for n in ['control','playback','final-control','final-playback'] if (root/n/'resources.dylib').exists()}
 print(json.dumps(r,indent=2));print('allsectionsmatch',all(s==next(iter(r.values())) for s in r.values()))
